<?php
declare(strict_types=1);
namespace App\Services;
use App\Support\Database;
final class FaqService { public function __construct(private ?Database $db){} public function public(array $country,string $language):array{if(!$this->db)return[];foreach([$language,app('countries')->defaultLanguage($country),'en']as$code){$rows=$this->db->select('SELECT f.* FROM faqs f INNER JOIN languages l ON l.id=f.language_id WHERE f.is_active=1 AND (f.country_id=? OR f.country_id IS NULL) AND l.code=? ORDER BY f.country_id IS NULL,f.sort_order,f.id',[$country['id'],$code]);if($rows)return$rows;}return[];}public function list(int $countryId):array{return $this->db?->select('SELECT f.*,l.code language_code FROM faqs f INNER JOIN languages l ON l.id=f.language_id WHERE f.country_id=? OR f.country_id IS NULL ORDER BY f.sort_order,f.id',[$countryId])??[];}public function save(array $data):int{if(!$this->db)throw new \RuntimeException('Database unavailable.');$this->db->execute('INSERT INTO faqs (country_id,language_id,category,question,answer,sort_order,is_active,created_at,updated_at) VALUES (?,?,?,?,?,?,?,NOW(),NOW())',[$data['country_id'],$data['language_id'],$data['category']?:null,$data['question'],$data['answer'],(int)$data['sort_order'],!empty($data['is_active'])?1:0]);return(int)$this->db->pdo()->lastInsertId();}public function update(int $id,array $data):void{$this->db?->execute('UPDATE faqs SET category=?,question=?,answer=?,sort_order=?,is_active=?,updated_at=NOW() WHERE id=?',[$data['category']?:null,$data['question'],$data['answer'],(int)$data['sort_order'],!empty($data['is_active'])?1:0,$id]);} }
